const shipNorm=(s)=>String(s==null?"":s).normalize("NFKC").replace(/\s+/g," ").trim().toLowerCase();
const getShip=(c)=>{if(!c)return"Unknown";if(c.ship)return c.ship;const m=SHIP_MAP[shipNorm(c.name)];if(m)return m;return ORG_SHIP_FALLBACK[c.org]||"Unknown";};
const lastMetricDate=(c)=>{if(!c||!Array.isArray(c.weekly))return null;for(let i=c.weekly.length-1;i>=0;i--){const w=c.weekly[i];if(w&&!w.nb&&!w.nr&&w.sd>0&&w.date)return w.date;}for(let i=c.weekly.length-1;i>=0;i--){const w=c.weekly[i];if(w&&w.date&&w.sd>0)return w.date;}return (c.wkAvg&&c.wkAvg.weekOf)||null;};
const fmtShipDate=(d)=>{if(!d)return"";const t=new Date(String(d)+"T00:00:00");if(isNaN(t.getTime()))return String(d);return t.toLocaleDateString("en-US",{day:"numeric",month:"short",year:"numeric"});};
const recentShipMove=(c)=>{if(!c||!c.shipMove||!c.shipMove.date)return null;const t=new Date(c.shipMove.date+"T00:00:00").getTime();if(isNaN(t))return null;const now=(typeof getESTNow==="function"?getESTNow().getTime():Date.now());return (now-t)<=28*86400000?c.shipMove:null;};
const lastVoyageEndOf=(c)=>{if(!c||!Array.isArray(c.weekly))return null;for(let i=c.weekly.length-1;i>=0;i--){const w=c.weekly[i];if(w&&!w.nb&&!w.nr&&w.sd>0&&w.date)return voyEndDate(w)||w.date;}for(let i=c.weekly.length-1;i>=0;i--){const w=c.weekly[i];if(w&&w.date&&w.sd>0)return voyEndDate(w)||w.date;}return (c.wkAvg&&c.wkAvg.weekOf)||null;};
const shipLabel=(c)=>{if(!c)return"Unknown";const active=lifecycleOf(c)==="active";if(active)return getShip(c);const d=lastVoyageEndOf(c);return d?("Inactive since - "+fmtShipDate(d)):"Inactive";};
const gapDays=(c)=>{const d=lastVoyageEndOf(c);if(!d)return 99999;const t=new Date(String(d)+"T00:00:00").getTime();if(isNaN(t))return 99999;const now=(typeof getESTNow==="function"?getESTNow().getTime():Date.now());return (now-t)/86400000;};
const typicalVoyDays=(c)=>{const v=(c&&Array.isArray(c.weekly)?c.weekly:[]).filter(w=>w&&!w.nb&&(w.vd||0)>0).slice(-6).map(w=>w.vd);return v.length?Math.max(...v):7;};
// Inactivity is voyage-aware: a long sailing plus end-of-voyage reconciliation must not read as absence.
// Trigger only when the gap since the last voyage END exceeds the person's own longest recent voyage plus a 10-day buffer (floor 14 days).
const inactiveCutoffDays=(c)=>Math.max(14,typicalVoyDays(c)+10);
const gapWeeks=(c)=>gapDays(c)/7;// retained for any legacy callers
const lifecycleOf=(c)=>{const gd=gapDays(c);const cut=inactiveCutoffDays(c);if(gd<cut)return"active";if(gd<=cut+56)return"grey";return"dormant";};// active within cutoff; grey for the next 8 weeks; dormant beyond
