// Palette for any fleet added later without an explicit config entry.
const FLEET_FALLBACK_PALETTE=["#7C3AED","#0891B2","#CA8A04","#BE185D","#15803D","#C2410C","#4338CA","#0F766E"];
const buildOrgs=(cands)=>{
  const slugs=[...new Set(cands.map(c=>c.org))];
  // Order cruise lines alphabetically by display label (EFFY always first).
  const labelFor=(slug)=>{const cfg=FLEET_CONFIG[slug];return cfg?cfg.label:slug.toUpperCase();};
  slugs.sort((a,b)=>labelFor(a).localeCompare(labelFor(b)));
  const orgs=[{id:"effy",label:"EFFY",base:"#0F766E",accent:C.teal,filter:()=>true,
    ombre:buildOmbre("#0F766E"),diamondColor:{main:0x0F766E,emissive:0x0F766E,glow:0x14B8A6,wire:0x5AB3AC}}];
  let fb=0;
  slugs.forEach(slug=>{
    const cfg=FLEET_CONFIG[slug];
    const base=cfg?cfg.base:FLEET_FALLBACK_PALETTE[fb++%FLEET_FALLBACK_PALETTE.length];
    const label=cfg?cfg.label:slug.toUpperCase();
    const diamond=cfg?cfg.diamond:{main:parseInt(base.slice(1),16),emissive:parseInt(base.slice(1),16),glow:0xFFFFFF,wire:0xCCCCCC};
    orgs.push({id:slug,label,base,accent:base,filter:c=>c.org===slug,ombre:buildOmbre(base),diamondColor:diamond});
  });
  return orgs;
};
