const avgMtd=(arr,field)=>arr.length?arr.reduce((a,c)=>a+(c.mtd?.[field]||0),0)/arr.length:0;
const sumMtd=(arr,field)=>arr.reduce((a,c)=>a+(c.mtd?.[field]||0),0);
const wAvgMtdSP=(arr)=>{let g=0,b=0;arr.forEach(c=>{const m=c.mtd||{};g+=(m.gap||0);b+=((m.sd||0)-(m.gap||0));});return b?g/b*100:0;};
const wAvgMtdAUR=(arr)=>{let s=0,u=0;arr.forEach(c=>{const m=c.mtd||{};if(m.aur>0){s+=(m.sd||0);u+=(m.sd||0)/m.aur;}});return u?s/u:0;};
const sumAcc=(arr,field)=>arr.reduce((a,c)=>a+(c.acc?.[field]||0),0);
const wAvgAccSP=(arr)=>{let g=0,b=0;arr.forEach(c=>{const m=c.acc||{};g+=(m.gap||0);b+=((m.sd||0)-(m.gap||0));});return b?g/b*100:0;};
const wAvgAccAUR=(arr)=>{let s=0,u=0;arr.forEach(c=>{const m=c.acc||{};if(m.aur>0){s+=(m.sd||0);u+=(m.sd||0)/m.aur;}});return u?s/u:0;};
