function WeeklySparkline({weekly,height=80}){
  const containerRef=useRef(null);
  const[dragOffset,setDragOffset]=useState(0);
  const dragRef=useRef({down:false,startX:0,startOff:0});
  const pts=(weekly||[]).filter(w=>!w.nb).map((w,i)=>({x:i,y:w.sp,label:`${w.m} V${w.v}`,sp:w.sp,nr:w.nr||0}));
  if(pts.length<2)return<div style={{height,display:"flex",alignItems:"center",justifyContent:"center",fontSize:10,color:C.muted}}>Insufficient weekly data</div>;
  const pointW=48;const totalW=pts.length*pointW;const pad=12;
  const minY=Math.min(...pts.map(p=>p.y)),maxY=Math.max(...pts.map(p=>p.y)),range=maxY-minY||1;
  const coords=pts.map((p,i)=>({x:pad+i*pointW,y:pad+(1-(p.y-minY)/range)*(height-pad*2-14),label:p.label,val:p.y,sp:p.sp}));
  const pathD=coords.map((c,i)=>i===0?`M${c.x},${c.y}`:`L${c.x},${c.y}`).join(" ");
  const gid="wsg"+Math.random().toString(36).slice(2,7);
  const maxScroll=Math.max(totalW-320,0);

  useEffect(()=>{setDragOffset(-maxScroll);},[weekly?.length]);
  const onDown=(e)=>{dragRef.current={down:true,startX:e.clientX||e.touches?.[0]?.clientX||0,startOff:dragOffset};};
  const onMove=(e)=>{if(!dragRef.current.down)return;const cx=e.clientX||e.touches?.[0]?.clientX||0;const dx=cx-dragRef.current.startX;setDragOffset(Math.max(-maxScroll,Math.min(0,dragRef.current.startOff+dx)));};
  const onUp=()=>{dragRef.current.down=false;};

  return(<div ref={containerRef} style={{width:"100%",height:height+16,overflow:"hidden",cursor:"grab",position:"relative",background:C.surface,borderRadius:8,border:`1px solid ${C.border}`}} onMouseDown={onDown} onMouseMove={onMove} onMouseUp={onUp} onMouseLeave={onUp} onTouchStart={onDown} onTouchMove={onMove} onTouchEnd={onUp}>
    {maxScroll>0&&<div style={{position:"absolute",top:4,left:8,fontSize:8,color:C.muted,zIndex:2,pointerEvents:"none"}}>Drag to view history</div>}
    <svg width={totalW+pad*2} height={height+16} style={{display:"block",transform:`translateX(${dragOffset}px)`,transition:dragRef.current.down?"none":"transform 0.15s ease"}}>
      <defs><linearGradient id={gid} x1="0%" x2="100%"><stop offset="0%" stopColor={C.red}/><stop offset="35%" stopColor={C.amber}/><stop offset="65%" stopColor={C.yellow}/><stop offset="100%" stopColor={C.green}/></linearGradient></defs>
      <line x1={pad} x2={totalW+pad} y1={pad+(1-(0-minY)/range)*(height-pad*2-14)} y2={pad+(1-(0-minY)/range)*(height-pad*2-14)} stroke={C.faint} strokeWidth="1" strokeDasharray="4,4"/>
      <path d={pathD} fill="none" stroke={`url(#${gid})`} strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"/>
      {coords.map((c,i)=>(<g key={i}><circle cx={c.x} cy={c.y} r="4" fill={pts[i].nr?C.muted:c.val>=0?C.green:C.red} stroke={pts[i].nr?"#999":"#fff"} strokeWidth="1.5" opacity={pts[i].nr?0.4:1}/>{pts[i].nr&&<text x={c.x} y={c.y-8} fontSize="6" fill={C.muted} textAnchor="middle">NR</text>}<text x={c.x} y={height+2} fontSize="7" fill={C.dim} textAnchor="middle">{c.label}</text></g>))}
    </svg>
  </div>);
}

